 if(fixedVersion){Check(!UI.GetComponentsInChildren<Text>().Any(t=>t.text=="Personaliza cómo quieres jugar."||t.text=="Preferencias personales"||t.text=="Perfiles recomendados"),"redundant panels removed");Check(UI.Find("unused")==null&&UI.GetComponentsInChildren<RectTransform>().Any(t=>t.name=="CompactProfileSummary"),"compact footer rendered");Fit();}
 a.MoveFocus(1);yield return Tick();var target=Controls[0].target;var scroll=target.GetComponentInParent<ScrollRect>();yield return Shot("focus-visible");scroll.verticalNormalizedPosition=0;yield return Tick();yield return Shot("focus-scrolled-out");
 target=Controls[0].target;scroll=target.GetComponentInParent<ScrollRect>();if(fixedVersion){Check(Focus.parent==target,"focus belongs to selected control, not overlay");Check(Focus.GetComponentInParent<RectMask2D>()==scroll.viewport.GetComponent<RectMask2D>(),"focus inherits same viewport mask");Check(Focus.anchorMin==Vector2.zero&&Focus.anchorMax==Vector2.one&&Focus.offsetMin==Vector2.zero&&Focus.offsetMax==Vector2.zero,"focus bounds match selected control");}
 a.MoveFocus(1);yield return Tick();var idx=(int)typeof(AccessController).GetField("focused",F).GetValue(a);var rt=(RectTransform)Controls[idx].target;scroll=rt.GetComponentInParent<ScrollRect>();var bounds=RectTransformUtility.CalculateRelativeRectTransformBounds(scroll.viewport,rt);Check(bounds.min.y>=scroll.viewport.rect.yMin-1&&bounds.max.y<=scroll.viewport.rect.yMax+1,"keyboard reveals next focused control");
 foreach(float scale in new[]{1.25f,1.5f,1.75f}){AccessPreferences.Current.textScale=scale;a.OpenCategory("Inicio");yield return Tick();if(fixedVersion)Fit();if(scale==1.75f){cards=Cards();Check(cards.All(c=>Mathf.Abs(c.anchoredPosition.x-cards[0].anchoredPosition.x)<1),"175 percent uses single column");yield return Shot("profiles-175");if(fixedVersion){a.MoveFocus(1);yield return Tick();var selectedControl=Controls[0].target;var maskScroll=selectedControl.GetComponentInParent<ScrollRect>();maskScroll.verticalNormalizedPosition=0;yield return Tick();yield return Shot("focus-175-outside");Check(Focus.GetComponentsInChildren<Graphic>().All(g=>g.canvasRenderer.cull),"renderer culls every focus edge when selected button is outside viewport");a.MoveFocus(1);yield return Tick();yield return Shot("focus-175-return");Check(Focus.GetComponentsInChildren<Graphic>().All(g=>!g.canvasRenderer.cull),"keyboard restores visible focus edges");}}}
 AccessPreferences.Current.textScale=1;a.OpenCategory("Audio");yield return Tick();a.MoveFocus(1);yield return Tick();if(fixedVersion)Check(Focus.parent==Controls[0].target&&Focus.GetComponentInParent<RectMask2D>()!=null,"shared audio focus inherits mask without altering controls");yield return Shot("audio-focus");
 if(fixedVersion){
  var asm=typeof(Editor).Assembly;var sizesType=asm.GetType("UnityEditor.GameViewSizes");var groupType=asm.GetType("UnityEditor.GameViewSizeGroupType");var sizeType=asm.GetType("UnityEditor.GameViewSize");var kind=asm.GetType("UnityEditor.GameViewSizeType");var flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;
  var sizes=sizesType.GetProperty("instance",BindingFlags.Public|BindingFlags.Static|BindingFlags.FlattenHierarchy).GetValue(null);var group=sizesType.GetMethod("GetGroup").Invoke(sizes,new[]{Enum.Parse(groupType,"Standalone")});var gt=group.GetType();int index=(int)gt.GetMethod("GetTotalCount").Invoke(group,null);
  var size=Activator.CreateInstance(sizeType,flags,null,new object[]{Enum.Parse(kind,"FixedResolution"),1280,720,"Profiles audit temporary"},null);gt.GetMethod("AddCustomSize").Invoke(group,new[]{size});var window=EditorWindow.GetWindow(asm.GetType("UnityEditor.GameView"));var selected=window.GetType().GetProperty("selectedSizeIndex",flags);int old=(int)selected.GetValue(window);selected.SetValue(window,index);yield return new WaitForSecondsRealtime(.5f);AccessPreferences.Current.textScale=1;a.OpenCategory("Inicio");yield return Tick();
  Check(Screen.width==1280&&Screen.height==720,"actual Game View renders at 1280x720");cards=Cards();Check(cards.All(c=>Mathf.Abs(c.anchoredPosition.x-cards[0].anchoredPosition.x)<1),"small resolution switches to single column");Fit();yield return Shot("profiles-1280x720");AccessPreferences.Current.textScale=1.75f;yield return Tick();Fit();yield return Shot("profiles-1280x720-175");selected.SetValue(window,old);gt.GetMethod("RemoveCustomSize").Invoke(group,new object[]{index});
