 log.Add("COMPLETE "+log.Count(x=>x.StartsWith("PASS "))+" PASS; Unity Play Mode, simulated focus/scroll; no physical device");File.WriteAllLines(dir+"/results.txt",log);EditorApplication.Exit(0);
