public static class ProfilesLayoutRunner {
 public static void Run(){SessionState.SetBool("ProfilesLayout",true);SessionState.SetString("ProfilesLayoutDir",Path.Combine(Path.GetTempPath(),"DespachoLayout-"+Guid.NewGuid().ToString("N")));EditorApplication.EnterPlaymode();}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Before(){if(!SessionState.GetBool("ProfilesLayout",false))return;DeskPreferences.TestDirectory=DeskSaveStore.TestDirectory=SessionState.GetString("ProfilesLayoutDir","");}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void After(){if(!SessionState.GetBool("ProfilesLayout",false))return;SessionState.SetBool("ProfilesLayout",false);new GameObject("ProfilesLayoutProbe").AddComponent<ProfilesLayoutProbe>();}
